def run(self, start_day: int, end_day: int) -> None:
    # rebuild if starting fresh
    if start_day == 0:
        self._build()
    window = []
    for t in range(start_day, end_day):
        self.state['time'] = t
        buffers = {}
        for module in self.modules:
            module.forward(self.state, buffers, self.params, t)
        self._commit(buffers)
        # Early stopping for convergence_check
        series = self.state['observables']['observable.adoption_rate_daily']
        if len(series) >= 8:
            diffs = [abs(series[-i] - series[-i-1]) for i in range(1, 8)]
            if max(diffs) < 0.005:
                break
